UPDATE provider_webhook_inbox
SET
status = 'RETRYABLE_FAILED',
retry_count = retry_count + 1,
next_retry_at = TIMESTAMPADD(
SECOND,
#{retryDelaySeconds},
CURRENT_TIMESTAMP(6)
),
claimed_by = NULL,
claimed_until = NULL,
last_error_code = #{errorCode},
last_error_message = #{errorMessage}
WHERE id = #{id}
AND status = 'PROCESSING'
AND claimed_by = #{workerId}
AND claim_version = #{claimVersion}
AND claimed_until >= CURRENT_TIMESTAMP(6)
AND retry_count + 1 < #{maxRetryCount}

UPDATE provider_webhook_inbox
SET
status = 'BLOCKED',
next_retry_at = NULL,
claimed_by = NULL,
claimed_until = NULL,
last_error_code = #{errorCode},
last_error_message = #{errorMessage}
WHERE id = #{id}
AND status = 'PROCESSING'
AND claimed_by = #{workerId}
AND claim_version = #{claimVersion}
AND claimed_until >= CURRENT_TIMESTAMP(6)

UPDATE provider_webhook_inbox
SET
claimed_until = TIMESTAMPADD(
SECOND,
#{leaseSeconds},
CURRENT_TIMESTAMP(6)
)
WHERE id = #{id}
AND status = 'PROCESSING'
AND claimed_by = #{workerId}
AND claim_version = #{claimVersion}
AND claimed_until >= CURRENT_TIMESTAMP(6)

UPDATE provider_webhook_inbox
SET
status = 'BLOCKED',
retry_count = retry_count + 1,
next_retry_at = NULL,
claimed_by = NULL,
claimed_until = NULL,
last_error_code = 'RETRY_EXHAUSTED',
last_error_message = #{errorMessage}
WHERE id = #{id}
AND status = 'PROCESSING'
AND claimed_by = #{workerId}
AND claim_version = #{claimVersion}
AND claimed_until >= CURRENT_TIMESTAMP(6)
AND retry_count + 1 >= #{maxRetryCount}
